    /// <summary>
    /// Severity levels for log messages produced by <see cref="Logger"/>.
    /// </summary>
    /// <remarks>
    /// Log levels determine which messages are actually output based on the active <see cref="ActualLogLevel"/>.
    /// Lower levels include all higher severity messages (e.g., <see cref="LogLevel.Error"/> includes Critical and Error).
    /// In DEBUG mode, the default level is <see cref="LogLevel.Debug"/>; in RELEASE, it is <see cref="LogLevel.Information"/>.
    /// </remarks>
    public enum LogLevel
    {
        None,
        Critical,
        Error,
        Warning,
        Information,
        Debug,
        Trace,
    }
